import threading

def reproduce(connect, service) -> str | None:
    N_each = 8
    N = N_each * 2
    barrier = threading.Barrier(N)
    deadlocks = []
    lock = threading.Lock()

    def worker(from_id, to_id):
        try:
            with connect() as conn:
                try:
                    barrier.wait(timeout=10)
                except Exception:
                    return
                try:
                    service.transfer(conn, from_id, to_id, 1)
                except Exception as e:
                    msg = f"{type(e).__name__}: {e}".lower()
                    if "deadlock" in msg:
                        with lock:
                            deadlocks.append(str(e))
                    # ignore other expected errors like InsufficientFunds for this repro
                    # but deadlock string check covers DeadlockDetected
                    try:
                        import psycopg.errors as pgerr
                        if isinstance(e, pgerr.DeadlockDetected):
                            with lock:
                                if not deadlocks:
                                    deadlocks.append(str(e))
                    except Exception:
                        pass
        except Exception:
            pass

    threads = []
    for i in range(N_each):
        threads.append(threading.Thread(target=worker, args=(1, 2)))
        threads.append(threading.Thread(target=worker, args=(2, 1)))
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=30)

    if deadlocks:
        return f"opposite transfers deadlocked ({len(deadlocks)} deadlock failures)"
    return None

